"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface SeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
  /** Optioneel label in het midden van de lijn. */
  label?: React.ReactNode;
}

/** Separator — dunne scheidingslijn, optioneel met label. */
export const Separator = React.forwardRef<HTMLDivElement, SeparatorProps>(function Separator(
  { orientation = "horizontal", label, className, ...rest },
  ref
) {
  if (label) {
    return (
      <div ref={ref} className={cn("pxui-separator-labelled", className)} {...rest}>
        <span className="pxui-separator-line" />
        <span className="pxui-separator-label">{label}</span>
        <span className="pxui-separator-line" />
      </div>
    );
  }

  return (
    <div
      ref={ref}
      role="separator"
      aria-orientation={orientation}
      className={cn("pxui-separator", `pxui-separator-${orientation}`, className)}
      {...rest}
    />
  );
});

/* ============================ Separator ============================ */
.pxui-separator { background: var(--border); border: none; flex: none; }
.pxui-separator-horizontal { height: 1px; width: 100%; }
.pxui-separator-vertical { width: 1px; align-self: stretch; min-height: 1em; }

.pxui-separator-labelled { display: flex; align-items: center; gap: 12px; width: 100%; }
.pxui-separator-labelled .pxui-separator-line { flex: 1; height: 1px; background: var(--border); }
.pxui-separator-label { font-size: var(--fs-sm); color: var(--text-3); font-weight: 550; white-space: nowrap; }
